+        this.clock = null;
+        this.maxAge = null;
+    }
+
+    public WorkRequestValidator(Clock clock, Duration maxAge) {
+        this.clock = Objects.requireNonNull(clock, "clock");
+        this.maxAge = Objects.requireNonNull(maxAge, "maxAge");
+    }
